<template><section class="manager"><header><div><h3><PosIcon name="layers" size="20" /> Batch Tracking &amp; FEFO</h3><p>Inventory batches and expiry allocation supplied by the backend.</p></div><span class="count">{{ nearExpiryCount }} near expiry · {{ expiredCount }} expired</span></header><p v-if="loading" class="state">Loading batches…</p><p v-else-if="error" class="state error">{{ error }}</p><p v-else-if="!batches.length" class="state">No inventory batches are available.</p><table v-else><thead><tr><th>Medication</th><th>Batch</th><th>Expiry</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="batch in batches" :key="batch.id"><td>{{ batch.name }}</td><td>{{ batch.batch_no }}</td><td>{{ batch.exp_date }}</td><td>{{ batch.stock_units }}</td><td>{{ status(batch) }}</td><td><button @click="pickBatch(batch)">Select</button></td></tr></tbody></table></section></template>
<script setup>
import { computed,onMounted,ref } from 'vue'; import { PosIcon } from '@pos/ui'; import { useApi } from '../../../../apps/pos/src/composables/useApi.js'
const emit=defineEmits(['notification']); const api=useApi(); const batches=ref([]); const loading=ref(true); const error=ref(''); onMounted(async()=>{try{const data=await api.get('/api/v1/pharmacy/batches');batches.value=data.items??[]}catch{error.value='Inventory batches could not be loaded. Please contact your administrator.'}finally{loading.value=false}})
const days=b=>Math.ceil((new Date(b.exp_date)-Date.now())/86400000); const nearExpiryCount=computed(()=>batches.value.filter(b=>days(b)>0&&days(b)<=60).length); const expiredCount=computed(()=>batches.value.filter(b=>days(b)<=0).length); function status(b){return days(b)<=0?'Expired':days(b)<=60?'Near expiry':'Good'} function pickBatch(b){emit('notification',{message:`Batch ${b.batch_no} selected for dispensing`,type:'success'})}
</script>
<style scoped>.manager{display:flex;flex-direction:column;gap:16px}header{display:flex;justify-content:space-between;gap:12px}h3{display:flex;align-items:center;gap:8px;margin:0;color:#1e293b}header p{margin:4px 0 0;color:#64748b;font-size:12px}.count{color:#64748b;font-size:11px}.state{padding:24px;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;text-align:center;font-size:12px}.state.error{border-color:#fecaca;color:#b91c1c}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:10px;text-align:left;border-bottom:1px solid #f1f5f9}th{color:#64748b}button{padding:6px 9px;border:0;border-radius:5px;background:#0284c7;color:#fff;font-size:11px;cursor:pointer}</style>
